 xy("Top source countries","bar_horizontal","FROM kibana_sample_data_logs | STATS requests = COUNT() BY country = geo.src | SORT requests DESC | LIMIT 10","country","requests",24,18,24,14),
 xy("Bytes transferred over time","area",f"FROM kibana_sample_data_logs | STATS total_bytes = SUM(bytes) BY time = {B}","time","total_bytes",0,32,48,10),
]
print(json.dumps({"title":"EFF-77649760 Web logs overview","description":"Overview of Kibana sample web logs: traffic volume, visitors, response sizes, error rate, top URLs and source countries.","time_range":{"from":"now-7d","to":"now"},"panels":panels}))
EOF
